// intent: Exercises object iterator prefix and postfix decrement operator targeting the fast path for object type.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    nlohmann::json j = {{"a", 1}, {"b", 2}, {"c", 3}};
    auto it = j.end();
    --it;
    std::cout << it.key() << ": " << it.value() << std::endl;
    it--;
    std::cout << it.key() << ": " << it.value() << std::endl;
    return 0;
}
